//! 🏟️ Native opening and unique registration conserve the exact observed five physical allocations.
use super::*;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
static REGISTRY:UiArenaRegistry=UiArenaRegistry::new();
struct Bank{left:RetainedCloneGrant,work:u64,born:usize,freed:usize}
impl Bank{
 fn new(c:&serde_json::Value)->Self{let s=&c["stock"];Self{left:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["fuel"].as_u64().unwrap(),born:0,freed:0}}
 fn grant(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,..self.left}}
 fn post(&mut self,p:RetainedCloneProgress,work:u64,heap:(usize,usize)){assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(self.grant()));self.left.maximum_items-=p.copied_items;self.left.maximum_copy_bytes-=p.copied_bytes;self.left.maximum_capacity_bytes-=p.retained_capacity_bytes;self.left.maximum_release_bytes-=p.released_bytes;self.work=self.work.checked_sub(work).expect("arena fixture requires its finite actual CPU stock");self.born+=p.retained_capacity_bytes;self.freed+=p.released_bytes;}
 fn logical<T>(&mut self,copy:usize,run:impl FnOnce()->T)->T{let g=self.grant();assert!(g.maximum_copy_bytes>=copy&&self.work>0);let(value,heap)=observe(run);self.post(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()},1,heap);value}
 fn step(&mut self,turn:RetainedWorkOutcome,heap:(usize,usize)){let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work,heap);turn.result.unwrap();}
}
fn open(c:&serde_json::Value,cut:Option<usize>,bank:&mut Bank)->Option<UiArenaBacking>{let mut opening=UiArenaOpening::new();let mut seen=0u16;for at in 0..100000{if cut==Some(at){break}if opening.ready(){break}let phase=opening.phase();let ordinal=c["opening"].as_array().unwrap().iter().position(|p|p==phase).unwrap();seen|=1<<ordinal;let d=opening.demands().unwrap();let g=bank.grant();for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}].into_iter().chain((d.capacity_bytes!=0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g})).chain((d.copy_bytes!=0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g})){let(turn,heap)=observe(||opening.advance(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(opening.phase(),phase);}let(turn,heap)=observe(||opening.advance(g));bank.step(turn,heap);}
 let out=if cut.is_none(){assert!(opening.ready());assert_eq!(seen,(1<<10)-1);let(turn,heap)=observe(||opening.take(bank.grant()));let(out,p)=turn.result.unwrap().unwrap();bank.post(p,turn.work,heap);Some(out)}else{None};for _ in 0..100000{if opening.terminal_is_empty(){break}let(turn,heap)=observe(||opening.close_step(bank.grant()));bank.step(turn,heap);}assert!(opening.terminal_is_empty());out}
#[test]
fn original_ui_arena_opening_and_registration_keep_actual_lifetime_owners(){let c:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for cut in c["cancelPrefixes"].as_array().unwrap(){let mut bank=Bank::new(&c);assert!(open(&c,Some(cut.as_u64().unwrap()as usize),&mut bank).is_none());assert_eq!(bank.born,bank.freed);}let mut bank=Bank::new(&c);let mut backing=open(&c,None,&mut bank);let pointer=backing.as_ref().unwrap().pointer().unwrap();let mut registered=None;let(turn,heap)=observe(||UiArenaRegistration::admit(&REGISTRY,&mut backing,&mut registered,bank.grant()));bank.step(turn,heap);assert!(backing.is_none());let registered=registered.as_mut().unwrap();let guard=REGISTRY.borrow().unwrap().unwrap();assert_eq!((&*guard)as*const UiValueArena as usize,pointer);let(turn,heap)=observe(||registered.close_step(bank.grant()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));drop(guard);
 let guard=REGISTRY.borrow_blocking().unwrap();assert_eq!((&*guard)as*const UiValueArena as usize,pointer);drop(guard);let handle=bank.logical(size_of::<UiCollectionSlot>(),||{let mut arena=REGISTRY.borrow().unwrap().unwrap();arena.reserve_collection(UiCollectionKind::List).unwrap()});let(turn,heap)=observe(||registered.close_step(bank.grant()));bank.step(turn,heap);assert!(registered.registered());{let mut arena=REGISTRY.borrow().unwrap().unwrap();bank.logical(size_of::<UiPageSlot>()+size_of::<UiCollectionSlot>(),||assert!(arena.try_push_page(handle,UiPageValue::List(UiValue::Null)).is_ok()));let root=bank.logical(size_of::<UiCollectionSlot>(),||arena.release_exact_handle(handle).unwrap().unwrap());for _ in 0..16{if arena.collection(root).is_none(){break}bank.logical(size_of::<UiPageSlot>()+size_of::<UiCollectionSlot>(),||arena.advance_exact_root(root,4096,&retirement::UI_VALUE_HANDBACKS).unwrap());}assert!(arena.collection(root).is_none());}
 for _ in 0..100000{if registered.terminal_is_empty(){break}let g=bank.grant();let d=registered.close_demands().unwrap();let denied=RetainedCloneGrant{maximum_items:0,..g};let(turn,heap)=observe(||registered.close_step(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));if d.release_bytes!=0{let(turn,heap)=observe(||registered.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}let(turn,heap)=observe(||registered.close_step(g));bank.step(turn,heap);}assert!(registered.terminal_is_empty());assert!(REGISTRY.borrow().is_err());assert_eq!(bank.born,bank.freed);assert!(bank.born>0&&bank.work>0);
}

#[test]
fn normal_arena_access_uses_the_actual_registered_source_backing(){
 let _serial=crate::test_arena::exclusive();let c:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let mut bank=Bank::new(&c);let mut backing=open(&c,None,&mut bank);let pointer=backing.as_ref().unwrap().pointer().unwrap();let mut registered=None;let(turn,heap)=observe(||UiArenaRegistration::admit(ui_value_arena_registry(),&mut backing,&mut registered,bank.grant()));bank.step(turn,heap);let actual=with_ui_value_arena(|arena|arena as*mut UiValueArena as usize);let registered=registered.as_mut().unwrap();for _ in 0..100000{if registered.terminal_is_empty(){break}let(turn,heap)=observe(||registered.close_step(bank.grant()));bank.step(turn,heap)}assert!(registered.terminal_is_empty());assert_eq!(bank.born,bank.freed);assert_eq!(actual,pointer,"normal access must borrow the registered Source backing");
}
